  'use server';

  import { getSession} from './session';
  import { redirect } from 'next/navigation';
  import { BACKEND_URL } from './constants';
  import { revalidatePath } from 'next/cache';

  export async function getApprovedPosts() {
      const session = await getSession();
      if (!session) redirect('/auth/signIn');
    
      try {
        const res = await fetch(`${BACKEND_URL}/post`, {
          headers: {
            Authorization: `Bearer ${session.accessToken}`,
          },
          cache: 'no-store',
        });
    
        if (!res.ok) throw new Error('Failed to load posts');
        return await res.json();
      } catch (err) {
        console.error('Error loading posts:', err);
        return [];
      }
    }

  export async function getPostById(postId: number) {
    const session = await getSession();
    if (!session) redirect('/auth/signIn');

    try {
      const res = await fetch(`${BACKEND_URL}/post/${postId}`, { cache: 'no-store' });
      if (!res.ok) throw new Error('Failed to fetch post');
      return await res.json();
    } catch (err) {
      console.error('Error fetching post:', err);
      return null;
    }
  }

  export async function createPost(formData: FormData) {
    const session = await getSession();
    if (!session) redirect('/auth/signIn');

    try {
      const res = await fetch(`${BACKEND_URL}/post`, {
        method: 'POST',
        headers: {
          Authorization: `Bearer ${session.accessToken}`,
        },
        body: formData,
      });

      if (!res.ok) throw new Error('Post creation failed');
      revalidatePath('/university');
      return await res.json();
    } catch (err) {
      console.error('Error creating post:', err);
      return null;
    }
  }

  export async function deletePost(postId: number) {
    const session = await getSession();
    if (!session) redirect('/auth/signIn');


    try { 
      const res = await fetch(`${BACKEND_URL}/post/${postId}`, {
        method: 'DELETE',
        headers: {
          Authorization: `Bearer ${session.accessToken}`,
        },
      });

      if (!res.ok) throw new Error('Delete failed');
      revalidatePath('/university');
    } catch (err) {
      console.error('Error deleting post:', err);
    }
  }
export async function getPostsByUser() {
  const session = await getSession();
  if (!session) redirect('/auth/signIn');

  const userId = session.user.id;

  try {
    const res = await fetch(`${BACKEND_URL}/post/user/${userId}`, {
      headers: {
        Authorization: `Bearer ${session.accessToken}`,
      },
      cache: 'no-store',
    });

    if (!res.ok) throw new Error('Failed to fetch user posts');
    return await res.json();
  } catch (err) {
    console.error('Error fetching user posts:', err);
    return [];
  }
}
export async function toggleSavePost(postId: number, isCurrentlySaved: boolean) {
  const session = await getSession();
  if (!session) redirect('/auth/signIn');

  try {
    const res = await fetch(`${BACKEND_URL}/post/${postId}/save`, {
      method: isCurrentlySaved ? 'DELETE' : 'POST',
      headers: {
        Authorization: `Bearer ${session.accessToken}`,
        'Content-Type': 'application/json',
      },
    });

    if (!res.ok) throw new Error('Failed to toggle save state');

    revalidatePath('/university');
    return await res.json();
  } catch (err) {
    console.error('❌ Error toggling save state:', err);
    return null;
  }
}

export async function getSuggestedEvents() {
  const session = await getSession();
  if (!session?.accessToken || !session?.user?.interests) return [];

  try {
    const res = await fetch(`${process.env.PUBLIC_BACKEND_URL}/events/suggested`, {
      headers: {
        Authorization: `Bearer ${session.accessToken}`,
        'Content-Type': 'application/json',
      },
      cache: 'no-store',
    });

    if (!res.ok) {
      const errorText = await res.text();
      console.error('❌ Failed to fetch suggested events:', res.status, errorText);
      return [];
    }

    return await res.json();
  } catch (err) {
    console.error('❌ Suggestion fetch error:', err);
    return [];
  }
}
